const PP_PART=[{group:"Maasai",countries:["Kenya", "Tanzania"],note:"62% / 38% split in Michalopoulos & Papaioannou.",src:[SRCQ("Michalopoulos & Papaioannou, The Long-Run Effects of the Scramble for Africa (CAGE working paper 162, 2013; published AER 2016)","https://warwick.ac.uk/fac/soc/economics/research/centres/cage/manage/publications/162-2013_stelios.pdf","Supports the Africa peoples, regions and borders page","the Maasai are partitioned between Kenya and Tanzania (shares 62% and 38%, respectively)")]},{group:"Ewe",countries:["Ghana", "Togo"],note:"Ghana and Togo disputed this boundary at independence; a UN plebiscite was held in British Togoland in 1956 (the plebiscite is not confirmed by the sources cited).",src:[SRCQ("Michalopoulos & Papaioannou, The Long-Run Effects of the Scramble for Africa (CAGE working paper 162, 2013; published AER 2016)","https://warwick.ac.uk/fac/soc/economics/research/centres/cage/manage/publications/162-2013_stelios.pdf","Supports the Africa peoples, regions and borders page","Ghana and Togo raised also objections on their boundary that splits the Ewe.")]},{group:"Somali",countries:["Somalia", "Ethiopia", "Kenya", "Djibouti"],note:"Split between British, Italian and French colonies, and Ethiopia. Somalia rejected the OAU border principle.",src:[SRCQ("Michalopoulos & Papaioannou, The Long-Run Effects of the Scramble for Africa (CAGE working paper 162, 2013; published AER 2016)","https://warwick.ac.uk/fac/soc/economics/research/centres/cage/manage/publications/162-2013_stelios.pdf","Supports the Africa peoples, regions and borders page","Somali tribes were split between three different European colonies"),SRCQ("Michalopoulos & Papaioannou, The Long-Run Effects of the Scramble for Africa (CAGE working paper 162, 2013; published AER 2016)","https://warwick.ac.uk/fac/soc/economics/research/centres/cage/manage/publications/162-2013_stelios.pdf","Supports the Africa peoples, regions and borders page","There are Somalis in Somalia, Ethiopia„ Kenya, and Djibouti.")]},{group:"Hausa",countries:["Nigeria", "Niger"],note:"Hausa is also a regional lingua franca.",src:[SRCQ("Michalopoulos & Papaioannou, The Long-Run Effects of the Scramble for Africa (CAGE working paper 162, 2013; published AER 2016)","https://warwick.ac.uk/fac/soc/economics/research/centres/cage/manage/publications/162-2013_stelios.pdf","Supports the Africa peoples, regions and borders page","the Hausa (split between Nigeria and Niger)")]},{group:"Bakongo",countries:["Angola", "DR Congo", "Republic of Congo"],note:"Heirs of the Kingdom of Kongo. Michalopoulos & Papaioannou quote Horowitz (1985): 'The Bakongo are divided among, Zaire, Congo (Brazzaville) and Angola'.",src:[SRCQ("Michalopoulos & Papaioannou, The Long-Run Effects of the Scramble for Africa (CAGE working paper 162, 2013; published AER 2016)","https://warwick.ac.uk/fac/soc/economics/research/centres/cage/manage/publications/162-2013_stelios.pdf","Supports the Africa peoples, regions and borders page","The Bakongo are divided among, Zaire, Congo (Brazzaville) and Angola")]},{group:"Chewa",countries:["Mozambique", "Malawi", "Zimbabwe"],note:"Shares on Murdock's 1959 map: Mozambique 50%, Malawi 34%, Zimbabwe 16%.",src:[SRCQ("Michalopoulos & Papaioannou, The Long-Run Effects of the Scramble for Africa (CAGE working paper 162, 2013; published AER 2016)","https://warwick.ac.uk/fac/soc/economics/research/centres/cage/manage/publications/162-2013_stelios.pdf","Supports the Africa peoples, regions and borders page","In the overwhelming majority of cases, European powers drew borders without taking into account local conditions."),SRCQ("Michalopoulos & Papaioannou, The Long-Run Effects of the Scramble for Africa (CAGE working paper 162, 2013; published AER 2016)","https://warwick.ac.uk/fac/soc/economics/research/centres/cage/manage/publications/162-2013_stelios.pdf","Supports the Africa peoples, regions and borders page","the Chewa between Mozambique (50%), Malawi (34%), and Zimbabwe (16%)")]},{group:"Malinke",countries:["six countries (the source does not list them)"],note:"The most divided group on the paper's index.",src:[SRCQ("Michalopoulos & Papaioannou, The Long-Run Effects of the Scramble for Africa (CAGE working paper 162, 2013; published AER 2016)","https://warwick.ac.uk/fac/soc/economics/research/centres/cage/manage/publications/162-2013_stelios.pdf","Supports the Africa peoples, regions and borders page","the Malinke, which are split into six different countries")]},{group:"Anyi",countries:["Ghana", "Côte d'Ivoire"],note:"58% Ghana, 42% Côte d'Ivoire, on Murdock's 1959 map.",src:[SRCQ("Michalopoulos & Papaioannou, The Long-Run Effects of the Scramble for Africa (CAGE working paper 162, 2013; published AER 2016)","https://warwick.ac.uk/fac/soc/economics/research/centres/cage/manage/publications/162-2013_stelios.pdf","Supports the Africa peoples, regions and borders page","There are 231 ethnic groups with at least 10% of their historical homeland falling into more than one contemporary state."),SRCQ("Michalopoulos & Papaioannou, The Long-Run Effects of the Scramble for Africa (CAGE working paper 162, 2013; published AER 2016)","https://warwick.ac.uk/fac/soc/economics/research/centres/cage/manage/publications/162-2013_stelios.pdf","Supports the Africa peoples, regions and borders page","the Anyi between Ghana and the Ivory Coast (shares 58% and 42%, respectively)")]}];
